-- Seed data PM dari export Google Sheets (pm.pdf) untuk MySQL / phpMyAdmin.
-- Impor: phpMyAdmin > pilih/buat database pm_backup > Import > file ini.

SET NAMES utf8mb4;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `audit_log`;

CREATE TABLE `audit_log` (
  `id` BIGINT NOT NULL,
  `at` LONGTEXT NULL,
  `deviceId` LONGTEXT NULL,
  `ip` LONGTEXT NULL,
  `action` LONGTEXT NULL,
  `recordId` LONGTEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `locks`;

CREATE TABLE `locks` (
  `scheduleId` VARCHAR(191) NOT NULL,
  `equipmentName` LONGTEXT NULL,
  `deviceId` LONGTEXT NULL,
  `name` LONGTEXT NULL,
  `acquiredAt` LONGTEXT NULL,
  `heartbeatAt` LONGTEXT NULL,
  PRIMARY KEY (`scheduleId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reports`;

CREATE TABLE `reports` (
  `id` VARCHAR(191) NOT NULL,
  `tagNo` LONGTEXT NULL,
  `date` LONGTEXT NULL,
  `equipmentType` LONGTEXT NULL,
  `equipmentName` LONGTEXT NULL,
  `unit` LONGTEXT NULL,
  `area` LONGTEXT NULL,
  `periode` LONGTEXT NULL,
  `week` BIGINT NULL,
  `month` BIGINT NULL,
  `teknisi` LONGTEXT NULL,
  `approval` LONGTEXT NULL,
  `notes` LONGTEXT NULL,
  `ppe` LONGTEXT NULL,
  `aktivitas` LONGTEXT NULL,
  `spareParts` LONGTEXT NULL,
  `submittedAt` LONGTEXT NULL,
  `updatedAt` LONGTEXT NULL,
  `deletedAt` LONGTEXT NULL,
  `updatedBy` LONGTEXT NULL,
  `serverAt` LONGTEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




DROP TABLE IF EXISTS `schedules`;

CREATE TABLE `schedules` (
  `id` VARCHAR(191) NOT NULL,
  `unit` LONGTEXT NULL,
  `area` LONGTEXT NULL,
  `equipment` LONGTEXT NULL,
  `tagNo` LONGTEXT NULL,
  `equipmentType` LONGTEXT NULL,
  `periode` LONGTEXT NULL,
  `month` BIGINT NULL,
  `week` BIGINT NULL,
  `pic` LONGTEXT NULL,
  `lastDone` LONGTEXT NULL,
  `mp` BIGINT NULL,
  `hari` BIGINT NULL,
  `notes` LONGTEXT NULL,
  `startDate` LONGTEXT NULL,
  `takeoverAt` LONGTEXT NULL,
  `takeoverFrom` LONGTEXT NULL,
  `takeoverReason` LONGTEXT NULL,
  `createdAt` LONGTEXT NULL,
  `updatedAt` LONGTEXT NULL,
  `deletedAt` LONGTEXT NULL,
  `updatedBy` LONGTEXT NULL,
  `serverAt` LONGTEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




DROP TABLE IF EXISTS `signatures`;

CREATE TABLE `signatures` (
  `pmId` VARCHAR(191) NOT NULL,
  `tagNo` LONGTEXT NULL,
  `equipmentName` LONGTEXT NULL,
  `tanggal` LONGTEXT NULL,
  `spvName` LONGTEXT NULL,
  `spvSignature` LONGTEXT NULL,
  `spvSignedAt` LONGTEXT NULL,
  `leaderName` LONGTEXT NULL,
  `leaderSignature` LONGTEXT NULL,
  `leaderSignedAt` LONGTEXT NULL,
  `updatedAt` LONGTEXT NULL,
  `updatedBy` LONGTEXT NULL,
  `serverAt` LONGTEXT NULL,
  PRIMARY KEY (`pmId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `templates`;

CREATE TABLE `templates` (
  `equipmentType` VARCHAR(191) NOT NULL,
  `items` LONGTEXT NULL,
  `updatedAt` LONGTEXT NULL,
  `updatedBy` LONGTEXT NULL,
  `serverAt` LONGTEXT NULL,
  PRIMARY KEY (`equipmentType`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
