INSERT INTO `templates` (`equipmentType`, `items`, `updatedAt`, `updatedBy`, `serverAt`) VALUES
('air_dryer', '[\"Bersihkan filter udara masuk dan keluar\",\"Periksa kondisi desiccant/molecular sieve\",\"Cek kebocoran pada fitting dan koneksi pipa\",\"Periksa tekanan inlet dan outlet\",\"Cek kondisi solenoid valve dan fungsinya\",\"Periksa arus motor dan koneksi kelistrikan\",\"Cek kondisi dan kebersihan cooler/heat exchanger\",\"Periksa drain valve dan pastikan berfungsi\",\"Lakukan pembersihan menyeluruh pada unit\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.374Z'),
('belt_conveyor', '[\"Bersihkan seluruh bagian mesin dari kotoran\",\"Periksa kondisi belt: keausan, sobekan, alignment\",\"Cek ketegangan belt dan sesuaikan jika diperlukan\",\"Periksa dan lumasi semua bearing pillow block\",\"Cek kondisi dan kekencangan baut-mur struktur\",\"Periksa kondisi pulley: keausan, kerak, alignment\",\"Cek kondisi skirt rubber dan belt cleaner\",\"Periksa sistem idler: semua berputar bebas\",\"Periksa arus motor dan semua koneksi kelistrikan\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.377Z'),
('blower', '[\"Bersihkan housing blower dari kotoran dan debu\",\"Periksa kondisi impeller/fan blade dari keausan\",\"Cek balancing impeller (tidak ada getaran berlebihan)\",\"Periksa dan lumasi bearing\",\"Cek kondisi belt: ketegangan dan keausan\",\"Periksa baut-mur pengikat dan kencangkan\",\"Periksa kondisi flexible coupling/joint\",\"Periksa arus motor dan koneksi kelistrikan\",\"Cek kondisi filter inlet jika ada\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.378Z'),
('bucket_elevator', '[\"Bersihkan bucket dan casing dari sisa material\",\"Periksa kondisi bucket: retak, bengkok, kehilangan baut\",\"Cek ketegangan chain/belt dan sesuaikan\",\"Periksa kondisi sprocket/pulley dari keausan\",\"Lumasi chain/bearing sesuai jadwal\",\"Periksa alignment head dan boot pulley\",\"Cek kondisi casing dan seal/gasket\",\"Periksa arus motor dan koneksi kelistrikan\",\"Periksa fungsi interlocking dan safety device\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.380Z'),
('cleaner', '[\"Bersihkan semua screen/ayakan dari material\",\"Periksa kondisi screen: sobekan, tersumbat, alignment\",\"Cek ketegangan belt dan semua V-belt\",\"Periksa kondisi bearing dan berikan pelumasan\",\"Periksa kondisi eccentric shaft dan lakukan pelumasan\",\"Cek kekencangan semua baut-mur\",\"Periksa kondisi aspirator dan air flow\",\"Periksa arus motor dan koneksi kelistrikan\",\"Pastikan semua cover pada tempatnya\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.382Z'),
('compressor', '[\"Periksa level oli dan tambahkan jika kurang\",\"Ganti filter udara jika sudah kotor/tersumbat\",\"Cek kondisi v-belt: ketegangan dan keausan\",\"Periksa safety valve dan pastikan berfungsi\",\"Drain kondensat dari tangki dan filter\",\"Periksa kebocoran pada fitting, pipa, dan sambungan\",\"Cek kondisi cylinder liner dan piston ring\",\"Periksa arus motor dan koneksi kelistrikan\",\"Cek fungsi pressure switch dan unloader valve\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.384Z'),
('dust_collector', '[\"Bersihkan atau ganti filter bag sesuai jadwal\",\"Periksa kondisi hopper dan pastikan tidak tersumbat\",\"Cek sistem screw conveyor di bawah hopper\",\"Periksa tekanan differential filter (ΔP)\",\"Cek sistem pulse jet cleaning dan solenoid valve\",\"Periksa kondisi fan/blower dan bearing\",\"Cek kondisi rotary valve/airlock\",\"Periksa arus motor dan koneksi kelistrikan\",\"Bersihkan area sekitar dust collector\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.386Z'),
('electric_panel', '[\"Bersihkan panel dari debu menggunakan vacuum/blower\",\"Periksa dan kencangkan semua terminal koneksi\",\"Cek kondisi MCB/MCCB/Fuse: tidak ada yang trip atau rusak\",\"Periksa kondisi kontaktor dan relay: fungsi normal\",\"Cek thermal relay setting vs nameplate motor\",\"Periksa kondisi kabel: tidak ada yang terkelupas\",\"Cek fungsi emergency stop dan interlocking\",\"Ukur tegangan supply dan catat\",\"Periksa kondisi PLC/inverter jika ada\",\"Cek sistem grounding/earthing\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.388Z'),
('gravity', '[\"Bersihkan deck screen dari material yang menempel\",\"Periksa kondisi deck: sobekan, keausan, alignment\",\"Cek ketegangan dan kondisi V-belt\",\"Periksa eksentrik/vibration mechanism\",\"Lumasi bearing sesuai jadwal\",\"Cek air flow di seluruh deck (distribusi merata)\",\"Periksa kekencangan semua baut-mur\",\"Periksa arus motor dan koneksi kelistrikan\",\"Pastikan semua adjustable outlet berfungsi\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.389Z'),
('packing_machine', '[\"Bersihkan semua bagian dari sisa bahan kimia\",\"Periksa kondisi dan kalibrasi load cell\",\"Cek kondisi dan bersihkan vertical/horizontal sealer\",\"Periksa ketajaman cutter\",\"Cek kondisi filter udara pada block regulator\",\"Periksa lubricator pneumatik dan level oli\",\"Periksa electrical valve dan koneksinya\",\"Ukur arus motor dan periksa koneksi kelistrikan\",\"Lakukan kalibrasi load cell\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.392Z'),
('pipe_gas', '[\"Pengecekan Kebocoran\",\"Pengecekan Valve\",\"Pengecekan Regulator\",\"Pengecekan Pressure Gauge\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.394Z'),
('screw_conveyor', '[\"Bersihkan seluruh bagian dari kotoran\",\"Periksa dan kencangkan semua baut-mur\",\"Pastikan semua cover terpasang\",\"Lumasi pillow block dan bearing\",\"Periksa gearbox: kebocoran oli dan level oli\",\"Cek kondisi screw (tidak berbenturan dengan body)\",\"Pastikan tidak ada kotoran yang menghambat screw\",\"Periksa arus motor dan koneksi kelistrikan\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.396Z'),
('sheller', '[\"Bersihkan kotoran pada unit penggerak\",\"Periksa mesh/ayakan dan bersihkan dari kotoran\",\"Periksa screw dan bersihkan dari material sisa\",\"Periksa dan bersihkan blower output\",\"Lumasi bearing dan cek V-belt\",\"Periksa kekencangan baut-mur pada struktur\",\"Periksa arus motor dan koneksi kelistrikan\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.398Z'),
('sliding_gate', '[\"Bersihkan area gate dari kotoran dan material sisa\",\"Periksa kondisi gate plate: keausan, kerataan\",\"Cek kondisi actuator/cylinder (pneumatik/elektrik)\",\"Periksa kebocoran pada sistem pneumatik jika ada\",\"Lumasi rail guide dan pivot point\",\"Cek kondisi limit switch dan proximity sensor\",\"Periksa kekencangan baut-mur pengikat\",\"Uji operasi buka-tutup beberapa kali\",\"Periksa koneksi kelistrikan dan kontrol\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.399Z'),
('treater', '[\"Bersihkan tangki dan nozzle dari endapan\",\"Periksa kondisi pompa dosing: flow rate akurat\",\"Kalibrasi flow meter dan pastikan akurasi\",\"Periksa kondisi selang dan fitting: tidak bocor\",\"Bersihkan atau ganti filter jika tersumbat\",\"Cek kondisi agitator/mixer\",\"Periksa sistem kontrol dan sensor level\",\"Periksa koneksi kelistrikan dan panel kontrol\",\"Bersihkan area sekitar treater dari tumpahan\"]', '2026-01-01T00:00:00.000Z', 'IMPORT-SHEETS', '2026-10-01T10:19:29.401Z');
